SELECT EXISTS (
    SELECT 1 FROM store WHERE store_id = #{storeId}
)

SELECT COUNT(*)
FROM alba
WHERE store_id = #{storeId}
  AND alba_phone = #{albaPhone}
  AND is_active = b'1'

  AND alba_id != #{excludeAlbaId}

SELECT COUNT(*)
FROM alba
WHERE store_id = #{storeId}
  AND alba_email = #{albaEmail}
  AND is_active = b'1'

  AND alba_id != #{excludeAlbaId}

mapper.update:
UPDATE alba
SET is_active = 0,
    updated_at = NOW()
WHERE alba_id = #{albaId}
  AND store_id = #{storeId}
  AND is_active = b'1'

